# 차량 상태로 도구 호출을 거르는 실행 관문 (가상 규칙)
RULES = {
    "seat_heat.off": {"block_if": lambda s: False, "confirm": False},
    "window.open": {"block_if": lambda s: s["speed"] > 0 and s["rain"], "confirm": False},
    "trunk.open": {"block_if": lambda s: s["gear"] != "P", "confirm": True},
    "message.send": {"block_if": lambda s: False, "confirm": True},
}


def gate(tool, s):
    r = RULES.get(tool)
    if r is None:
        return "BLOCK(모르는 도구)"
    if r["block_if"](s):
        return "BLOCK(차량 상태)"
    return "CONFIRM" if r["confirm"] else "RUN"


state = {"speed": 62, "gear": "D", "rain": True}
for t in ["seat_heat.off", "window.open", "trunk.open", "message.send", "sunroof.tilt"]:
    print(f"{t:14} -> {gate(t, state)}")
# seat_heat.off  -> RUN
# window.open    -> BLOCK(차량 상태)
# trunk.open     -> BLOCK(차량 상태)
# message.send   -> CONFIRM
# sunroof.tilt   -> BLOCK(모르는 도구)
